#!/usr/bin/env python3
"""Parse two unified diffs and emit an HTML fragment (diff sections only) for the review page."""
import html
import re
import sys

def parse_diff(path):
    """Return list of hunks: [{'header': str, 'lines': [(kind, text), ...]}]"""
    hunks = []
    current = None
    with open(path, encoding="utf-8") as f:
        for raw in f:
            line = raw.rstrip("\n")
            if line.startswith("@@"):
                if current:
                    hunks.append(current)
                current = {"header": line, "lines": []}
            elif current is not None:
                if line.startswith("+"):
                    current["lines"].append(("add", line[1:]))
                elif line.startswith("-"):
                    current["lines"].append(("rem", line[1:]))
                elif line.startswith("\\"):
                    current["lines"].append(("meta", line))
                else:
                    current["lines"].append(("ctx", line[1:] if line.startswith(" ") else line))
    if current:
        hunks.append(current)
    return hunks


def render_hunks(hunks, anchor_prefix):
    out = []
    for i, hunk in enumerate(hunks):
        out.append(f'<div class="hunk" id="{anchor_prefix}-h{i}">')
        out.append(f'<div class="hunk-head">{html.escape(hunk["header"])}</div>')
        out.append('<div class="hunk-body">')
        for kind, text in hunk["lines"]:
            cls = {"add": "ln add", "rem": "ln rem", "ctx": "ln ctx", "meta": "ln meta"}[kind]
            marker = {"add": "+", "rem": "−", "ctx": " ", "meta": " "}[kind]
            out.append(f'<div class="{cls}"><span class="mk">{marker}</span><span class="tx">{html.escape(text) if text else "&nbsp;"}</span></div>')
        out.append('</div></div>')
    return "\n".join(out)


if __name__ == "__main__":
    ah_hunks = parse_diff(sys.argv[1])
    test_hunks = parse_diff(sys.argv[2])
    with open(sys.argv[3], "w", encoding="utf-8") as f:
        f.write("<!-- ALL_HANTA -->\n")
        f.write(render_hunks(ah_hunks, "ah"))
        f.write("\n<!-- TEST_ALL_HANTA -->\n")
        f.write(render_hunks(test_hunks, "test"))
    print("ah hunks:", len(ah_hunks), "test hunks:", len(test_hunks))

